//! Current-request PDF ranges and cancellable streaming cache identity.
use std::{fs::File,io::{Read,Seek,SeekFrom},path::{Path,PathBuf},os::windows::io::AsRawHandle};
use sha2::{Digest,Sha256};
pub const CHUNK:u64=1024*1024;
pub const MAX_BYTES:u64=2*1024*1024*1024;
#[repr(C)]#[derive(Default)]struct Info{attributes:u32,created:[u32;2],accessed:[u32;2],written:[u32;2],volume:u32,size_high:u32,size_low:u32,links:u32,index_high:u32,index_low:u32}
#[repr(C)]#[derive(Default)]struct Basic{created:i64,accessed:i64,written:i64,changed:i64,attributes:u32}
#[link(name="kernel32")]extern "system"{fn GetFileInformationByHandle(h:*mut std::ffi::c_void,i:*mut Info)->i32;fn GetFileInformationByHandleEx(h:*mut std::ffi::c_void,class:i32,i:*mut std::ffi::c_void,size:u32)->i32;}
#[derive(Clone,PartialEq,Debug)]struct Identity{size:u64,volume:u32,index:u64,created:i64,written:i64,changed:i64}
fn identity(file:&File)->Result<Identity,String>{let mut i=Info::default();let mut b=Basic::default();if unsafe{GetFileInformationByHandle(file.as_raw_handle(),&mut i)}==0||unsafe{GetFileInformationByHandleEx(file.as_raw_handle(),0,(&mut b as *mut Basic).cast(),std::mem::size_of::<Basic>() as u32)}==0||i.attributes&0x10!=0{return Err("Cannot identify this PDF file.".into())}Ok(Identity{size:(u64::from(i.size_high)<<32)|u64::from(i.size_low),volume:i.volume,index:(u64::from(i.index_high)<<32)|u64::from(i.index_low),created:b.created,written:b.written,changed:b.changed})}
#[derive(Clone)]pub struct Session{pub owner:u64,path:PathBuf,identity:Identity}
impl Session{
 pub fn open(owner:u64,path:&Path)->Result<Self,String>{if crate::file_service::format_kind(path)!="pdf"{return Err("PDF ranges require a PDF request.".into())}let mut f=File::open(path).map_err(|e|e.to_string())?;let id=identity(&f)?;if id.size<5||id.size>MAX_BYTES{return Err("PDFs must be nonempty and at most 2 GiB.".into())}let mut header=[0;5];f.read_exact(&mut header).map_err(|e|e.to_string())?;if &header!=b"%PDF-"{return Err("This is not a valid PDF file.".into())}if identity(&f)?!=id{return Err("The PDF changed while opening. Reopen it.".into())}Ok(Self{owner,path:path.to_owned(),identity:id})}
 pub fn length(&self)->u64{self.identity.size}
 pub fn cache_identity(&self)->String{use std::os::windows::ffi::OsStrExt;let mut hash=crate::ocr_cache::Session::hasher();hash.update(format!("pdf-file-identity-v1:{:?}",self.identity));for c in self.path.as_os_str().encode_wide(){hash.update(c.to_le_bytes())}format!("{:x}",hash.finalize())}
 fn file(&self,owner:u64)->Result<File,String>{if owner!=self.owner{return Err("Preview cancelled.".into())}let f=File::open(&self.path).map_err(|e|e.to_string())?;if identity(&f)?!=self.identity{return Err("The PDF changed. Reopen it to continue.".into())}Ok(f)}
 pub fn check(&self,owner:u64)->Result<(),String>{self.file(owner).map(|_|())}
 pub fn read(&self,owner:u64,begin:u64,end:u64)->Result<Vec<u8>,String>{if end<=begin||end>self.length()||end-begin>CHUNK{return Err("Invalid or excessive PDF range.".into())}let mut f=self.file(owner)?;let mut bytes=vec![0;(end-begin) as usize];f.seek(SeekFrom::Start(begin)).and_then(|_|f.read_exact(&mut bytes)).map_err(|e|e.to_string())?;if identity(&f)?!=self.identity{return Err("The PDF changed while reading. Reopen it.".into())}self.check(owner)?;Ok(bytes)}
 pub fn digest(&self,owner:u64,mut hasher:Sha256,live:impl Fn()->bool)->Result<String,String>{let mut f=self.file(owner)?;let mut buffer=vec![0;CHUNK as usize];let mut count=0;loop{if !live(){return Err("Preview cancelled.".into())}let read=f.read(&mut buffer).map_err(|e|e.to_string())?;if read==0{break}count+=read as u64;if count>self.length(){return Err("The PDF grew while indexing.".into())}hasher.update(&buffer[..read]);std::thread::sleep(std::time::Duration::from_millis(2));}if count!=self.length()||identity(&f)?!=self.identity{return Err("The PDF changed while indexing.".into())}self.check(owner)?;if !live(){return Err("Preview cancelled.".into())}Ok(format!("{:x}",hasher.finalize()))}
}
#[cfg(test)]mod tests{
 use super::*;use std::io::Write;
 #[test]fn bounded_ranges_and_hash_detect_changes_and_preserve_sources(){let root=std::env::temp_dir().join(format!("av-pdf-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&root).unwrap();let path=root.join("range.pdf");let mut f=File::create(&path).unwrap();f.write_all(b"%PDF-1.7\n").unwrap();f.set_len(129*1024*1024).unwrap();f.seek(SeekFrom::End(-4)).unwrap();f.write_all(b"tail").unwrap();drop(f);let s=Session::open(7,&path).unwrap();assert_eq!(s.read(7,s.length()-4,s.length()).unwrap(),b"tail");assert!(s.read(8,0,5).is_err());assert!(s.read(7,0,CHUNK+1).is_err());assert!(s.read(7,s.length(),s.length()+1).is_err());assert!(s.digest(7,Sha256::new(),||false).is_err());assert_eq!(std::fs::metadata(&path).unwrap().len(),s.length());let mut f=std::fs::OpenOptions::new().write(true).open(&path).unwrap();f.seek(SeekFrom::Start(8)).unwrap();f.write_all(b"x").unwrap();drop(f);assert!(s.read(7,0,5).is_err());std::fs::remove_dir_all(root).unwrap();}
}
